def format_bytes(n):
    """Return a human-readable size such as '1.5 KB'."""
    steps = ["B", "KB", "MB", "GB", "TB", "PB"]
    size = float(n)
    for unit in steps:
        if size < 1024.0 or unit == steps[-1]:
            if unit == "B":
                return f"{int(size)} {unit}"
            return f"{size:.1f} {unit}"
        size /= 1024.0
